"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[175],{1442:(e,a,o)=>{o.d(a,{cn:()=>n});function n(...e){return e.filter(Boolean).join(" ")}},2379:(e,a,o)=>{o.d(a,{_:()=>n,r:()=>i});let n={name:"NOCTUA",legalName:"NOCTUA SpA",rut:"77.890.441-3",tagline:"Se nombra de noche.",description:"Centro m\xe9dico de precisi\xf3n en Vitacura. Ocho especialidades, laboratorio e imagen en la misma casa. Abrimos a las 16:00. \xdaltimo cupo 22:00.",url:"https://noctuamedico.cl",email:"hora@noctuamedico.cl",phone:"+56 2 3288 4050",phoneHref:"tel:+56232884050",mobile:"+56 9 7612 4050",mobileHref:"tel:+56976124050",whatsapp:"+56 9 7612 4050",whatsappHref:"https://wa.me/56976124050?text=Hola%20NOCTUA%2C%20quiero%20pedir%20una%20hora.",instagram:"https://instagram.com/noctua.medico",instagramHandle:"@noctua.medico",coords:{lat:"33\xb023′S",lng:"70\xb035′W"},geo:{lat:-33.383,lng:-70.583},address:{line1:"Av. Nueva Costanera 4050",commune:"Vitacura",city:"Santiago",region:"Regi\xf3n Metropolitana",country:"Chile",maps:"https://maps.google.com/?q=Av.+Nueva+Costanera+4050+Vitacura"},metro:"Escuela Militar \xb7 12 min a pie",parking:"Ocho cupos en el predio \xb7 aviso al agendar",hoursShort:"Lun–Vie 16:00–23:00 \xb7 S\xe1b 09:00–14:00",hours:[{days:"Lunes a viernes",time:"16:00 – 23:00"},{days:"S\xe1bado",time:"09:00 – 14:00"},{days:"Domingo y festivos",time:"Cerrado"}],lastSlot:"22:00",openHour:16,closeHour:23,saturdayOpen:9,saturdayClose:14,founded:2018,emergency:"131"},i=[{href:"/especialidades",label:"Especialidades"},{href:"/sueno",label:"Sue\xf1o"},{href:"/casa",label:"La casa"},{href:"/equipo",label:"Equipo"}]},2381:(e,a,o)=>{o.d(a,{IO:()=>r,Q0:()=>l,V5:()=>n,kL:()=>i,tO:()=>s});let n=[{slug:"medicina-interna",n:"01",room:"Sala 01",title:"Medicina interna",forWhom:"Quien trae tres recetas de tres m\xe9dicos que no se hablan. El chequeo que no es un paquete de mall. El s\xedntoma que no cierra en una especialidad.",duration:"40 min",priceFrom:48e3,image:"/images/consulta.jpg",alt:"Sala de consulta NOCTUA: camilla de lino oscuro, fonendo y l\xe1mpara \xe1mbar",lead:"El mapa entero, no un \xf3rgano suelto. Cuarenta minutos para ordenar lo que el d\xeda fragment\xf3.",body:"De d\xeda el internista es una hora que no existe: se pide para agosto. Aqu\xed la consulta cabe despu\xe9s del trabajo. Elisa mira junto lo que suele verse por separado — la presi\xf3n, el az\xfacar, el sue\xf1o, el \xe1nimo, los remedios del velador. Si el caso pide cardiolog\xeda, imagen o un examen, la derivaci\xf3n ocurre esa misma noche, con nombre y con hora.",includes:["Chequeo anual con plan escrito esa noche","Hipertensi\xf3n, dislipidemia y riesgo cardiovascular","S\xedntomas que no cierran en una especialidad","Polifarmacia y revisi\xf3n de recetas","Coordinaci\xf3n de ex\xe1menes en esta casa"],when:["Hace m\xe1s de un a\xf1o que nadie lo mira entero","Trae tres recetas que no se hablan","Quiere un chequeo que no sea un paquete"],doctorSlug:"elisa-moreno",star:{x:86,y:118}},{slug:"medicina-del-sueno",n:"02",room:"Sala de sue\xf1o",title:"Medicina del sue\xf1o",forWhom:"Quien se acuesta y no apaga. El que ronca y nadie midi\xf3. La somnolencia que el caf\xe9 ya no cubre. El insomnio que ya tiene apellido y no tiene plan.",duration:"50 min \xb7 estudio 8 h",priceFrom:58e3,image:"/images/sueno.jpg",alt:"Habitaci\xf3n de estudio de sue\xf1o NOCTUA: cama de lino, l\xe1mpara baja y los Andes al fondo",lead:"La noche no se consulta de d\xeda. Vicente lee lo que el cuerpo hace cuando nadie lo mira.",body:"Insomnio, apnea, piernas inquietas, el turno que desorden\xf3 el reloj. La primera hora es una conversaci\xf3n de cincuenta minutos: historia, escalas, hip\xf3tesis. Si hace falta polisomnograf\xeda, se duerme aqu\xed — no en un s\xf3tano de otro recinto. El informe vuelve a esta sala. No vendemos un aparato de entrada. Nombramos primero.",includes:["Consulta de sue\xf1o de 50 minutos","Polisomnograf\xeda en esta casa, una noche","Titulaci\xf3n de CPAP cuando corresponde","Insomnio con plan, no con un sobre de pastillas","Informe para el internista o el cardi\xf3logo de esta casa"],when:["Se acuesta y el d\xeda no se apaga","Le dijeron que ronca y nadie midi\xf3","El caf\xe9 ya no cubre la somnolencia"],doctorSlug:"vicente-araya",star:{x:160,y:52}},{slug:"cardiologia",n:"03",room:"Sala 03",title:"Cardiolog\xeda",forWhom:"Las palpitaciones que llegan a las once. La presi\xf3n que no baja. El control despu\xe9s del infarto. El certificado que pidi\xf3 otra cirug\xeda.",duration:"40 min",priceFrom:64e3,image:"/images/still.jpg",alt:"Tira de electrocardiograma bajo luz \xe1mbar sobre piedra oscura",lead:"Francisca no consulta el pecho por WhatsApp. La primera hora incluye ECG en la misma sala.",body:"El coraz\xf3n tambi\xe9n tiene una noche: arritmias que de d\xeda no aparecen, la presi\xf3n que sube cuando Santiago duerme. Prevenci\xf3n, insuficiencia, el control despu\xe9s del infarto. Si hace falta eco, Holter o MAPA, se agenda en esta casa. Un pecho que aprieta ahora se atiende en urgencia — no en esta sala, y se lo decimos en la web y en el tel\xe9fono.",includes:["Prevenci\xf3n cardiovascular y control de factores","ECG de doce derivaciones en la misma hora","Ecocardiograma, Holter y MAPA en esta casa","Seguimiento post infarto o angioplastia","Evaluaci\xf3n preoperatoria cardiol\xf3gica"],when:["Hay palpitaciones, disnea o presi\xf3n que no baja","Le dijeron que el coraz\xf3n est\xe1 bien y no le mostraron nada","Le pidieron un certificado para una cirug\xeda"],doctorSlug:"francisca-leon",star:{x:234,y:118}},{slug:"neurologia",n:"04",room:"Sala 04",title:"Neurolog\xeda",forWhom:"La cefalea que llega a las seis. El temblor que alguien llam\xf3 estr\xe9s. El mareo que no es del o\xeddo. La duda que un scanner no cerr\xf3.",duration:"40 min",priceFrom:62e3,image:"/images/ventana.jpg",alt:"Ventana de NOCTUA hacia Santiago y los Andes, de noche",lead:"Mart\xedn nombra la se\xf1al. Si es imagen, se hace aqu\xed. Si es urgencia, se dice.",body:"Migra\xf1a, cefalea tensional, el aura que asusta. Epilepsia que ya tiene nombre y pide seguimiento de noche. El temblor, la neuropat\xeda, el mareo que no cierra en otorrino. La resonancia, cuando corresponde, se coordina en esta casa — no con un papel y un \xabpida usted\xbb. Un d\xe9ficit brusco, una cara que cae, un lenguaje que se pierde: eso es SAMU 131.",includes:["Migra\xf1a y cefalea con plan, no con un AINE suelto","Epilepsia y seguimiento de tratamiento","Temblor, neuropat\xeda y mareo de origen central","Lectura de im\xe1genes con usted, no por correo","Derivaci\xf3n a sue\xf1o cuando el s\xedntoma duerme mal"],when:["La cefalea ya no responde a lo de siempre","Hay un temblor, un mareo o una duda de imagen","Quiere un neur\xf3logo que no mire el reloj a los doce minutos"],doctorSlug:"martin-urrutia",star:{x:160,y:148}},{slug:"salud-mental",n:"05",room:"Sala 05",title:"Salud mental",forWhom:"La cabeza que no apaga a las once. La ansiedad que el d\xeda disfraza. El \xe1nimo que baj\xf3 y nadie le puso tiempo. El insomnio que ya no es solo sue\xf1o.",duration:"50 min",priceFrom:52e3,image:"/images/espera.jpg",alt:"Pabell\xf3n de espera NOCTUA: sillas de lino oscuro, l\xe1mpara \xe1mbar y jard\xedn de noche",lead:"Isidora reserva cincuenta minutos. No es un recetario. Tampoco es urgencia psiqui\xe1trica.",body:"La noche destapa lo que el escritorio sostiene: ansiedad, insomnio, el \xe1nimo que se fue apagando. Primera hora de cincuenta minutos, el mismo m\xe9dico de principio a fin. Coordinamos con sue\xf1o y con interna cuando el caso lo pide — la ficha es una. Un riesgo suicida, una crisis psic\xf3tica, un menor en descompensaci\xf3n: eso no se atiende aqu\xed. Se deriva, y se llama al 131 si hace falta.",includes:["Consulta de 50 minutos, sin recorte","Insomnio, ansiedad y \xe1nimo — mapa, no etiqueta suelta","Ajuste de tratamiento con seguimiento","Coordinaci\xf3n con medicina del sue\xf1o","Informe para el internista de esta casa, si lo pide"],when:["La cabeza no apaga cuando el d\xeda termina","El \xe1nimo cambi\xf3 y quiere tiempo, no una receta de pasillo","El insomnio ya no se arregla con higiene de sue\xf1o"],doctorSlug:"isidora-paredes",star:{x:78,y:212}},{slug:"ginecologia",n:"06",room:"Sala 06",title:"Ginecolog\xeda",forWhom:"El PAP pendiente. El ciclo que cambi\xf3. La menopausia de la que nadie habla con tiempo. El control que no cabe a las ocho de la ma\xf1ana.",duration:"40 min",priceFrom:54e3,image:"/images/mesa.jpg",alt:"Mesa de consulta: cuaderno de lino, pluma y vaso de agua bajo l\xe1mpara \xe1mbar",lead:"Camila reserva el tiempo del examen y el de lo que lo rodea. El PAP cabe. La conversaci\xf3n tambi\xe9n.",body:"Hay consultas de ginecolog\xeda que duran lo que dura un PAP. En esta sala el examen cabe, y cabe lo que lo rodea: el ciclo, el deseo, la anticoncepci\xf3n, el sangrado, la menopausia. Ecograf\xeda ginecol\xf3gica en casa cuando corresponde. Abrimos a las 16:00 porque esa hora tambi\xe9n es de quien trabaja. Si hay que derivar a oncolog\xeda o a medicina reproductiva, se hace con nombre.",includes:["Control ginecol\xf3gico, PAP y VPH","Anticoncepci\xf3n y consejer\xeda","Sangrado, miomas y endometriosis","Climaterio y menopausia","Ecograf\xeda ginecol\xf3gica en esta casa"],when:["Lleva a\xf1os sin un control y no puede pedir la ma\xf1ana","Hay dolor, sangrado o un PAP pendiente","Quiere hablar de menopausia con alguien que escuche"],doctorSlug:"camila-fuentes",star:{x:242,y:212}},{slug:"imagenologia",n:"07",room:"Sala de imagen",title:"Imagenolog\xeda",forWhom:"La eco que no quiere viajar a otro edificio. La resonancia que de d\xeda tiene lista de espera. El informe que debe volver a la sala que lo pidi\xf3.",duration:"15–45 min",priceFrom:48e3,image:"/images/imagen.jpg",alt:"Sala de resonancia NOCTUA de noche, luces \xe1mbar y una rendija de luna",lead:"Andr\xe9s opera cuando la ciudad baja el ruido. La m\xe1quina oye mejor. El informe vuelve esa noche.",body:"Ecograf\xeda, radiograf\xeda, resonancia. No es un s\xf3tano de otro recinto: es esta casa, despu\xe9s de las 16:00, cuando el pasillo est\xe1 en silencio. El informe no viaja una semana. Vuelve al m\xe9dico que lo pidi\xf3. Si el estudio pide contraste o un pabell\xf3n que no cabe aqu\xed, se deriva — no se improvisa.",includes:["Ecograf\xeda abdominal, tiroidea y ginecol\xf3gica","Radiograf\xeda digital, informe el mismo d\xeda","Resonancia coordinada en horario nocturno","Lectura con el m\xe9dico tratante de esta casa","Portal de resultados al despertar, o antes"],when:["Le pidieron una eco y no quiere otro edificio","La lista de espera de d\xeda no le cabe","Quiere que el informe vuelva a quien lo pidi\xf3"],doctorSlug:"andres-valdivia",star:{x:118,y:268}},{slug:"laboratorio",n:"08",room:"Laboratorio",title:"Laboratorio",forWhom:"El perfil que no quiere otra fila a las siete de la ma\xf1ana. El control de la tiroides. El resultado que el internista de esta casa va a leer.",duration:"10–20 min",priceFrom:14e3,image:"/images/lab.jpg",alt:"Laboratorio NOCTUA: microscopio, gradilla de vidrio y l\xe1mpara \xe1mbar",lead:"Paula extrae de noche y el s\xe1bado de ayuno. El n\xfamero vuelve a la ficha, no a un PDF suelto.",body:"Hemograma, perfil, HbA1c, tiroides, vitamina D. Toma de muestra de lunes a viernes desde las 16:00 — con indicaci\xf3n de ayuno vespertino cuando corresponde — y el s\xe1bado de 09:00 a 11:30 para quien necesita la ventana cl\xe1sica. El resultado entra al portal y a la sala que lo pidi\xf3. No somos un laboratorio de mall: si el examen no se procesa aqu\xed, se dice.",includes:["Toma de muestra lun–vie desde 16:00","Ayuno de s\xe1bado 09:00 a 11:30","Hemograma, perfil, HbA1c, tiroides","Resultado en portal, la mayor\xeda el mismo d\xeda","La cifra entra a la ficha de esta casa"],when:["Le pidieron un perfil y no puede madrugar","Quiere que el internista lea el n\xfamero, no un PDF","Necesita un control de tiroides o de az\xfacar"],doctorSlug:"paula-henriquez",star:{x:202,y:268}}],i=[{q:"\xbfPor qu\xe9 abren a las 16:00?",a:"Porque la consulta de quien trabaja no cabe a las ocho de la ma\xf1ana. NOCTUA est\xe1 pensado para despu\xe9s del sol: \xfaltimo cupo 22:00, lunes a viernes. El s\xe1bado es 09:00 a 14:00 — ayuno de laboratorio hasta las 11:30, consultas hasta las 14:00."},{q:"\xbfSon un servicio de urgencia?",a:"No. Somos un centro m\xe9dico de precisi\xf3n con horario nocturno. Atendemos consulta, laboratorio e imagen. Un pecho que aprieta, una cara que cae, una disnea grave o un trauma se atienden en un servicio de urgencia. SAMU 131. En /urgencia est\xe1 el mapa de qu\xe9 s\xed y qu\xe9 no."},{q:"\xbfAtienden ISAPRE y FONASA?",a:"Bono electr\xf3nico. Boleta reembolsable el mismo d\xeda. Particular, ISAPRE (Banm\xe9dica, Colmena, Consalud, Cruz Blanca, Nueva Masvida, Vida Tres y otras) y FONASA. El porcentaje lo define tu plan: te orientamos con el c\xf3digo y el tope, no prometemos un n\xfamero que no controlamos."},{q:"\xbfEl laboratorio pide ayuno de madrugada?",a:"El s\xe1bado, s\xed: 09:00 a 11:30. De lunes a viernes tomamos muestra desde las 16:00, con indicaci\xf3n de ayuno vespertino cuando el examen lo permite. Si el an\xe1lisis exige la ventana cl\xe1sica de la ma\xf1ana, lo decimos al agendar — no te hacemos venir de noche para un n\xfamero que no sirve."},{q:"\xbfCu\xe1nto cuesta la primera consulta?",a:"Medicina interna, $48.000 \xb7 40 minutos. Sue\xf1o, $58.000 \xb7 50 minutos. Cardiolog\xeda, $64.000, con ECG en la misma hora. Los valores son referenciales \xabdesde\xbb y se confirman al agendar. Tel\xe9fono: +56 2 3288 4050."},{q:"\xbfC\xf3mo cancelo o reprogramo?",a:"Por WhatsApp o al +56 2 3288 4050, con 24 horas de anticipaci\xf3n. Menos que eso, se cobra la hora: el cupo es de una persona, no de una lista. Responden de la casa, no un call center."}],r=["Particular","Banm\xe9dica","Colmena","Consalud","Cruz Blanca","Esencial","Nueva Masvida","Vida Tres","FONASA","Otra"],l=["16:00","17:00","18:00","19:00","20:00","21:00","22:00"],s=[["medicina-del-sueno","medicina-interna"],["medicina-del-sueno","cardiologia"],["medicina-interna","neurologia"],["cardiologia","neurologia"],["medicina-interna","salud-mental"],["cardiologia","ginecologia"],["salud-mental","imagenologia"],["ginecologia","laboratorio"],["imagenologia","laboratorio"],["neurologia","imagenologia"],["neurologia","laboratorio"]]},5985:(e,a,o)=>{o.r(a),o.d(a,{Reveal:()=>l});var n=o(5155),i=o(2115),r=o(1442);function l({children:e,className:a,delay:o=0}){let s=(0,i.useRef)(null);return(0,i.useEffect)(()=>{let e=s.current;if(!e)return;if(window.matchMedia("(prefers-reduced-motion: reduce)").matches)return void e.classList.add("is-visible");let a=new IntersectionObserver(([o])=>{o.isIntersecting&&(e.classList.add("is-visible"),a.disconnect())},{threshold:.16,rootMargin:"0px 0px -8% 0px"});return a.observe(e),()=>a.disconnect()},[]),(0,n.jsx)("div",{ref:s,className:(0,r.cn)("reveal",a),style:{transitionDelay:`${o}ms`},children:e})}}}]);